mapper.sql:
hi.apt_seq,
hi.sgg_cd,
hi.umd_cd,
hi.umd_nm,
hi.jibun,
hi.road_nm_sgg_cd,
hi.road_nm,
hi.road_nm_bonbun,
hi.road_nm_bubun,
hi.apt_nm,
hi.build_year,
hi.latitude,
hi.longitude,
dc.sido_name,
dc.gugun_name,

(SELECT COUNT(*) FROM housedeals hd WHERE hd.apt_seq = hi.apt_seq

        AND CAST(REPLACE(COALESCE(hd.deal_amount, '0'), ',', '') AS UNSIGNED) >= #{dealAmountMin}


        AND CAST(REPLACE(COALESCE(hd.deal_amount, '0'), ',', '') AS UNSIGNED) <= #{dealAmountMax}

) AS deal_count,
(SELECT CAST(AVG(CAST(REPLACE(COALESCE(hd2.deal_amount, '0'), ',', '') AS UNSIGNED)) AS SIGNED)
 FROM housedeals hd2 WHERE hd2.apt_seq = hi.apt_seq

        AND CAST(REPLACE(COALESCE(hd2.deal_amount, '0'), ',', '') AS UNSIGNED) >= #{dealAmountMin}


        AND CAST(REPLACE(COALESCE(hd2.deal_amount, '0'), ',', '') AS UNSIGNED) <= #{dealAmountMax}

) AS avg_price,



        (SELECT COUNT(*) FROM houserents hr WHERE hr.apt_seq = hi.apt_seq
            AND hr.monthly_rent = 0
            AND hr.deposit >= #{depositMin}
            AND hr.deposit <= #{depositMax}
        ) AS rent_count,
        (SELECT CAST(AVG(hr.deposit) AS SIGNED) FROM houserents hr WHERE hr.apt_seq = hi.apt_seq
            AND hr.monthly_rent = 0
            AND hr.deposit >= #{depositMin}
            AND hr.deposit <= #{depositMax}
        ) AS avg_deposit,
        0 AS avg_monthly_rent


        (SELECT COUNT(*) FROM houserents hr WHERE hr.apt_seq = hi.apt_seq
            AND hr.monthly_rent > 0
            AND hr.deposit >= #{depositMin}
            AND hr.deposit <= #{depositMax}
            AND hr.monthly_rent >= #{monthlyRentMin}
            AND hr.monthly_rent <= #{monthlyRentMax}
        ) AS rent_count,
        (SELECT CAST(AVG(hr.deposit) AS SIGNED) FROM houserents hr WHERE hr.apt_seq = hi.apt_seq
            AND hr.monthly_rent > 0
            AND hr.deposit >= #{depositMin}
            AND hr.deposit <= #{depositMax}
            AND hr.monthly_rent >= #{monthlyRentMin}
            AND hr.monthly_rent <= #{monthlyRentMax}
        ) AS avg_deposit,
        (SELECT CAST(AVG(hr.monthly_rent) AS SIGNED) FROM houserents hr WHERE hr.apt_seq = hi.apt_seq
            AND hr.monthly_rent > 0
            AND hr.deposit >= #{depositMin}
            AND hr.deposit <= #{depositMax}
            AND hr.monthly_rent >= #{monthlyRentMin}
            AND hr.monthly_rent <= #{monthlyRentMax}
        ) AS avg_monthly_rent


        0 AS rent_count,
        NULL AS avg_deposit,
        NULL AS avg_monthly_rent

mapper.select:
SELECT

FROM houseinfos hi
LEFT JOIN dongcodes dc ON dc.dong_code = CONCAT(hi.sgg_cd, hi.umd_cd)





                AND CONCAT(hi.sgg_cd, hi.umd_cd) = #{sigunguCode}


                AND hi.sgg_cd = #{sigunguCode}




        AND hi.umd_nm LIKE CONCAT('%', #{dongName}, '%')


        AND hi.apt_nm LIKE CONCAT('%', #{keyword}, '%')




            AND EXISTS (
                SELECT 1
                FROM houserents hr
                WHERE hr.apt_seq = hi.apt_seq
                  AND hr.monthly_rent = 0

                    AND hr.deposit >= #{depositMin}


                    AND hr.deposit <= #{depositMax}

            )


            AND EXISTS (
                SELECT 1
                FROM houserents hr
                WHERE hr.apt_seq = hi.apt_seq
                  AND hr.monthly_rent > 0

                    AND hr.deposit >= #{depositMin}


                    AND hr.deposit <= #{depositMax}


                    AND hr.monthly_rent >= #{monthlyRentMin}


                    AND hr.monthly_rent <= #{monthlyRentMax}

            )


            AND EXISTS (
                SELECT 1
                FROM housedeals hd
                WHERE hd.apt_seq = hi.apt_seq

                    AND CAST(REPLACE(COALESCE(hd.deal_amount, '0'), ',', '') AS UNSIGNED) >= #{dealAmountMin}


                    AND CAST(REPLACE(COALESCE(hd.deal_amount, '0'), ',', '') AS UNSIGNED) <= #{dealAmountMax}

            )



ORDER BY hi.apt_nm ASC
LIMIT 200

mapper.update:
UPDATE houseinfos
SET apt_nm = #{aptNm},
    build_year = #{buildYear},
    latitude = #{latitude},
    longitude = #{longitude}
WHERE apt_seq = #{aptSeq}

choose.when:
SELECT CONCAT('rent-', hr.rent_id) AS id, hr.apt_seq, 'apt' AS housing_type, 'rent' AS contract_type, COALESCE(hi.apt_nm, '') AS name, COALESCE(hi.umd_nm, '') AS dong, COALESCE(hi.umd_nm, '') AS emd, COALESCE(hi.jibun, '') AS lot, COALESCE(hi.sgg_cd, '') AS region_code, hr.deposit AS amount, hr.deposit, hr.monthly_rent, hr.exclu_use_ar AS area, CAST(REPLACE(COALESCE(hr.floor, '0'), ',', '') AS SIGNED) AS floor, CASE WHEN hr.deal_year > 0 AND hr.deal_month > 0 AND hr.deal_day > 0 THEN DATE_FORMAT(STR_TO_DATE(CONCAT(hr.deal_year, LPAD(hr.deal_month, 2, '0'), LPAD(hr.deal_day, 2, '0')), '%Y%m%d'), '%Y-%m-%d') ELSE '' END AS date, CASE WHEN hr.deal_year > 0 AND hr.deal_month > 0 THEN CONCAT(hr.deal_year, LPAD(hr.deal_month, 2, '0')) ELSE '' END AS deal_ymd FROM houserents hr JOIN houseinfos hi ON hr.apt_seq = hi.apt_seq WHERE hr.apt_seq = #{aptSeq}
AND hr.monthly_rent = 0
AND hr.monthly_rent > 0
ORDER BY hr.deal_year DESC, hr.deal_month DESC, hr.deal_day DESC, hr.rent_id DESC LIMIT #{limit}
